.tpg{width:100%;max-width:520px;padding:0;overflow:hidden}
.tpg-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 12px}
.tpg-t{margin-top:2px;font-size:16px;font-weight:600;color:var(--text)}
.tpg-list{display:flex;flex-direction:column;padding:0 8px 8px}
.tpg-r{position:relative;display:grid;grid-template-columns:22px 28px minmax(0,1fr) 64px 56px 52px;align-items:center;gap:10px;height:46px;padding:0 8px;cursor:default}
.tpg-r::before{content:"";position:absolute;inset:4px 0;width:var(--w,0%);background:var(--accent-bg);transition:width .7s cubic-bezier(.16,1,.3,1)}
.tpg-r:hover::after{content:"";position:absolute;inset:4px 0;border:1px solid var(--line);pointer-events:none}
.tpg-r > *{position:relative}
.tpg-rk{font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted)}
.tpg-ic{display:grid;place-items:center;width:28px;height:28px;background:var(--panel);border:1px solid var(--line);color:var(--text-dim)}
.tpg-ic .ms{font-size:15px}
.tpg-p{display:flex;flex-direction:column;min-width:0}
.tpg-p b{font-family:var(--mono);font-size:12.5px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tpg-p span{font-size:11.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tpg-sp{width:64px;height:22px}
.tpg-sp polyline{fill:none;stroke:var(--accent-hi);stroke-width:1.6;stroke-linejoin:round;stroke-linecap:round}
.tpg-v{font-family:var(--mono);font-size:12.5px;font-weight:700;color:var(--text);text-align:right}
.tpg-c{justify-self:end;padding:1px 6px;font-family:var(--mono);font-size:10.5px;font-weight:700}
.tpg-c.up{color:#159a63;background:color-mix(in srgb,#159a63 10%,transparent)}
.tpg-c.down{color:#e5484d;background:color-mix(in srgb,#e5484d 10%,transparent)}
[data-style="soft"] .tpg{border-radius:22px}
[data-style="soft"] .tpg-r::before,[data-style="soft"] .tpg-r:hover::after{border-radius:12px}
[data-style="soft"] .tpg-ic{border-radius:9px}
[data-style="soft"] .tpg-rk,[data-style="soft"] .tpg-v,[data-style="soft"] .tpg-c,[data-style="soft"] .tpg-p b{font-family:var(--sans);font-weight:600}
[data-style="soft"] .tpg-c{border-radius:999px}

