  const list = $('#tpg-list');
  const PAGES = [['/pricing','Pricing','bar_chart',12400,486,12],['/','Home','home',9800,212,4],['/lab','The Lab','stars',7200,318,38],['/components/status-pill','Status pill','description',4100,96,-3],['/blog/agent-ui','Designing agent UI','edit_note',3300,141,22],['/changelog','Changelog','refresh',2100,38,-8]];
  const sp = seed => { const r = rng(seed); let v = 10; const pts = Array.from({ length:12 }, (_, i) => `${(i / 11 * 64).toFixed(1)},${(20 - (v = Math.max(2, Math.min(18, v + (r() - .42) * 6)))).toFixed(1)}`).join(' '); return `<svg class="tpg-sp" viewBox="0 0 64 22"><polyline points="${pts}"/></svg>`; };
  list.innerHTML = PAGES.map((p, i) => `<div class="tpg-r" data-i="${i}"><span class="tpg-rk"></span><span class="tpg-ic">${ic(p[2],'sm')}</span><span class="tpg-p"><b>${p[0]}</b><span>${p[1]}</span></span>${sp(i * 7 + 3)}<span class="tpg-v"></span><span class="tpg-c ${p[5] >= 0 ? 'up' : 'down'}">${p[5] >= 0 ? '+' : '\u2212'}${Math.abs(p[5])}%</span></div>`).join('');
  hydrate(list);
  function show(k, animate){
    const rows = $$('.tpg-r', list), key = k === 'v' ? 3 : 4, max = Math.max(...PAGES.map(p => p[key]));
    const order = [...PAGES.keys()].sort((a, b) => PAGES[b][key] - PAGES[a][key]);
    const before = new Map(rows.map(r => [r, r.getBoundingClientRect().top]));
    order.forEach((i, n) => { const r = rows[i]; list.appendChild(r); r.querySelector('.tpg-rk').textContent = String(n + 1).padStart(2, '0'); r.querySelector('.tpg-v').textContent = PAGES[i][key].toLocaleString('en-US'); r.style.setProperty('--w', (PAGES[i][key] / max * 100).toFixed(1) + '%'); });
    if (animate && !reduce) rows.forEach(r => { const d = before.get(r) - r.getBoundingClientRect().top; if (Math.abs(d) > 1) r.animate([{ transform:`translateY(${d}px)` }, { transform:'none' }], { duration:520, easing:'cubic-bezier(.16,1,.3,1)' }); });
  }
  // bars grow in when the list comes into view
  $$('.tpg-r', list).forEach(r => r.style.setProperty('--w', '0%'));
  whenSeen($('#c103'), () => show('v', false));
  segInit($('#tpg-seg'), v => { show(v, true); Sound.play('tab'); });
}
